-- V5_1（SQL Server）申込の申込者 ID を NULL 可にする（申込者アカウントは一次承認が通ったときに発行して紐づける）。
-- 列に依存する外部キーと索引をいったん外してから列定義を変える。外部キーは V5_3 で改名後のテーブルへ張り直す
ALTER TABLE T_APPLICATION DROP CONSTRAINT FK_T_APPLICATION_APPLICANT;
DROP INDEX IX_T_APPLICATION_03 ON T_APPLICATION;
ALTER TABLE T_APPLICATION ALTER COLUMN APPLICANT_ID BIGINT NULL;
CREATE INDEX IX_T_APPLICATION_03 ON T_APPLICATION (APPLICANT_ID);
